/**
 * Invented league for the props board V1 tests: all 30 franchises, 8 invented "Demo" players each, two seasons.
 * Nothing here is real. Players, ids, minutes and box scores are generated by fixed formulas.
 *
 * Slot 3 of every team (position SF) plays exactly 30 minutes with 15 PTS, 6 REB, 3 AST in every game, so the
 * baseline projection for that player has an exact hand-computable answer (15, 6, 3 for PTS, REB, AST).
 */
import { CANONICAL_TEAM_CODES } from "../canonical";
import { PLAYER_GAMES_SCHEMA } from "../v1/playerGameImport";
import { POSITION_ESTIMATES_SCHEMA } from "../v1/positionEstimates";

export const FIXTURE_SOURCE_ID = "balldontlie" as const;
export const FIXTURE_RETRIEVED_AT = "2026-10-23T12:00:00Z";
export const FIXTURE_BUILD_AT = "2026-10-24T15:00:00Z";
export const FIXTURE_GAME_KEY = "2026-10-24|BOS@NYK";
export const FIXTURE_TIPOFF = "2026-10-24T23:30:00Z";
const MINUTES = [34, 32, 30, 28, 26, 18, 14, 10] as const;
const POSITIONS = ["PG", "SG", "SF", "PF", "C", "PG", "SF", "C"] as const;
const ROLES = ["starter", "starter", "starter", "starter", "starter", "rotation", "rotation", "bench"] as const;
const PRIOR_ROUNDS = 12;
const CURRENT_ROUNDS = 2;
const DAY_MS = 24 * 3600 * 1000;

const teams = [...CANONICAL_TEAM_CODES];
export const fixtureName = (team: string, slot: number): string => `Demo Player ${team} ${slot}`;
export const fixtureId = (team: string, slot: number): string => `${team}-${slot}`;

function box(slot: number, opponentIndex: number): { minutes: number; pts: number; reb: number; ast: number } {
  const minutes = MINUTES[slot - 1];
  // Only slots 1 and 2 react to the opponent, so DvP differs by team and slot 3 stays exactly constant.
  const bonus = slot <= 2 ? opponentIndex % 4 : 0;
  return { minutes, pts: Math.round(minutes * 0.5) + bonus, reb: Math.round(minutes * 0.2), ast: Math.round(minutes * 0.1) };
}

interface Row {
  season: string; seasonType: string; gameId: string; gameDate: string; team: string; opponent: string; isHome: boolean;
  playerId: string; playerName: string; minutes: number; pts: number; reb: number; ast: number;
}

function roundRows(season: string, round: number, date: string, skip: (team: string, slot: number) => boolean): Row[] {
  const rows: Row[] = [];
  for (let i = 0; i < 15; i += 1) {
    const home = teams[i];
    const away = teams[15 + ((i + round) % 15)];
    const gameId = `${season}-r${round}-${home}-${away}`;
    for (const [team, opponent, isHome] of [[home, away, true], [away, home, false]] as const) {
      for (let slot = 1; slot <= 8; slot += 1) {
        if (skip(team, slot)) continue;
        rows.push({ season, seasonType: "regular", gameId, gameDate: date, team, opponent, isHome, playerId: fixtureId(team, slot), playerName: fixtureName(team, slot), ...box(slot, teams.indexOf(opponent)) });
      }
    }
  }
  return rows;
}

export function fixtureRows(): Row[] {
  const rows: Row[] = [];
  for (let r = 1; r <= PRIOR_ROUNDS; r += 1) rows.push(...roundRows("2025-26", r, new Date(Date.UTC(2025, 10, 1) + r * 3 * DAY_MS).toISOString().slice(0, 10), () => false));
  for (let r = 1; r <= CURRENT_ROUNDS; r += 1) rows.push(...roundRows("2026-27", r, new Date(Date.UTC(2026, 9, 18) + r * 2 * DAY_MS).toISOString().slice(0, 10), () => false));
  return rows;
}

export function fixtureImportFile(over: { rows?: Row[]; sourceId?: string; retrievedAtUtc?: string } = {}): unknown {
  return {
    schemaVersion: PLAYER_GAMES_SCHEMA,
    source: { sourceId: over.sourceId ?? FIXTURE_SOURCE_ID, retrievedAtUtc: over.retrievedAtUtc ?? FIXTURE_RETRIEVED_AT, provenance: "invented fixture data for tests; not a real export" },
    rows: over.rows ?? fixtureRows(),
  };
}

/** Estimates for one season. `without` leaves a player out, as a real file might miss a player. */
export function fixturePositionsFile(season: "2025-26" | "2026-27", without: readonly string[] = []): unknown {
  const players = teams.flatMap((team) =>
    MINUTES.map((_, i) => ({ playerId: fixtureId(team, i + 1), name: fixtureName(team, i + 1), team, primary: POSITIONS[i], secondary: [], role: ROLES[i] })),
  ).filter((p) => !without.includes(p.playerId));
  const extra = season === "2026-27" ? [{ playerId: "DEN-9", name: "Demo Rookie DEN 9", team: "DEN", primary: "PG", secondary: [], role: "bench" }] : [];
  return { schemaVersion: POSITION_ESTIMATES_SCHEMA, season, asOfUtc: season === "2026-27" ? "2026-10-22T00:00:00Z" : "2026-04-10T00:00:00Z", sourceNote: "invented depth chart for tests; not a real source", players: [...players, ...extra], overrides: [] };
}

export const fixtureSlateFile = (): unknown => ({ season: "2026-27", games: [{ gameKey: FIXTURE_GAME_KEY, tipoffUtc: FIXTURE_TIPOFF }] });
